#!/usr/bin/env python3
"""Runs every scenario, writes RESULTS.md, results.json and timing_diagram.png."""
import json, os, time
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from scenarios import SCENARIOS

HERE = os.path.dirname(os.path.abspath(__file__))
out = ["# Simulation results (model-in-the-loop)\n",
       "> Generated by `run_simulation.py`. **These are results of a software model** (Python port of the PLC "
       "sequence + assumed plant physics). They show that the sequence design behaves as intended against the "
       "assumptions; they are not measurements and do not validate machine performance.\n"]
allres, total, passed = {}, 0, 0
for name, fn in SCENARIOS:
    t0 = time.time(); res, checks, rig = fn()
    allres[name] = dict(result=res, checks=[[c, bool(ok)] for c, ok in checks])
    out.append(f"\n## {name}\n")
    out.append("| Check | Result |\n|---|---|")
    for c, ok in checks:
        total += 1; passed += bool(ok); out.append(f"| {c} | {'PASS' if ok else '**FAIL**'} |")
    out.append("\n```json\n" + json.dumps(res, indent=1) + "\n```")
    print(f"{name:55s} {sum(ok for _, ok in checks)}/{len(checks)}  ({time.time() - t0:.1f}s)")
    if name.startswith("S01"):
        tr = rig.trace; t = [x[0] - tr[0][0] for x in tr]
        fig, ax = plt.subplots(7, 1, figsize=(11, 8.5), sharex=True)
        series = [("PLC step", [x[1] for x in tr]), ("jaw position (1=closed)", [x[2] for x in tr]),
                  ("vertical seal bar", [x[3] for x in tr]), ("knife", [x[4] for x in tr]),
                  ("film speed mm/s", [x[5] for x in tr]), ("dump request / product falling", [x[6] + 0.5 * x[7] for x in tr]),
                  ("product above jaws g", [x[9] for x in tr])]
        for a, (lab, y) in zip(ax, series):
            a.step(t, y, where="post", lw=1.0); a.set_ylabel(lab, rotation=0, ha="right", va="center", fontsize=8); a.grid(alpha=0.3)
        ax[-1].set_xlabel("time s (simulated, 40 g chips, bag 230 mm)")
        fig.suptitle("SPM-420 cycle timing - SIMULATED, not measured", fontsize=10); fig.tight_layout()
        fig.savefig(os.path.join(HERE, "timing_diagram.png"), dpi=120)
        fig.savefig(os.path.join(HERE, "..", "AUTOMATION", "SEQUENCES", "timing_diagram_simulated.png"), dpi=120)
out.insert(2, f"\n**{passed} of {total} checks passed.**\n")
open(os.path.join(HERE, "RESULTS.md"), "w").write("\n".join(out) + "\n")
json.dump(allres, open(os.path.join(HERE, "results.json"), "w"), indent=1)
print(f"{passed}/{total} checks passed")
